import numpy as np

def softmax(x):
    """x: (..., n_classes) - handles arbitrary batch dims"""
    x = x - x.max(axis=-1, keepdims=True)  # stability
    e_x = np.exp(x)
    return e_x / e_x.sum(axis=-1, keepdims=True)

def softmax_grad(x):
    """Jacobian of softmax. Useful for backprop derivations."""
    s = softmax(x)  # (n,)
    return np.diag(s) - np.outer(s, s)  # (n, n)

from openai import OpenAI
import numpy as np

client = OpenAI()

def embed(text):
    return np.array(client.embeddings.create(
        input=text, model="text-embedding-3-small"
    ).data[0].embedding)

def cosine_sim(a, b):
    return np.dot(a, b) / (np.linalg.norm(a) * np.linalg.norm(b) + 1e-9)

class SimpleRAG:
    def __init__(self):
        self.chunks = []     # list of (text, embedding)

    def ingest(self, documents, chunk_size=500):
        for doc in documents:
            # Simple fixed-size chunking
            words = doc.split()
            for i in range(0, len(words), chunk_size - 50):
                chunk = " ".join(words[i:i + chunk_size])
                emb = embed(chunk)
                self.chunks.append((chunk, emb))

    def retrieve(self, query, k=3):
        q_emb = embed(query)
        scores = [(cosine_sim(q_emb, emb), text)
                  for text, emb in self.chunks]
        scores.sort(reverse=True)
        return [text for _, text in scores[:k]]

    def query(self, question, k=3):
        retrieved = self.retrieve(question, k)
        context = "\n\n---\n\n".join(retrieved)
        prompt = f"""Answer based on the context below.
Context:
{context}

Question: {question}
Answer:"""
        resp = client.chat.completions.create(
            model="gpt-4o-mini",
            messages=[{"role": "user", "content": prompt}]
        )
        return resp.choices[0].message.content

import numpy as np

def iou_matrix(a, b):
    x1 = np.maximum(a[:, None, 0], b[None, :, 0]); y1 = np.maximum(a[:, None, 1], b[None, :, 1])
    x2 = np.minimum(a[:, None, 2], b[None, :, 2]); y2 = np.minimum(a[:, None, 3], b[None, :, 3])
    inter = np.clip(x2 - x1, 0, None) * np.clip(y2 - y1, 0, None)
    area = lambda z: (z[:, 2] - z[:, 0]) * (z[:, 3] - z[:, 1])
    return inter / (area(a)[:, None] + area(b)[None, :] - inter + 1e-9)

def average_precision(preds, gts, iou_thr=0.5):
    """AP for ONE class at ONE IoU threshold.
    preds: list of (image_id, score, box[4]); gts: dict image_id -> (G,4) array.
    All-point interpolation (area under the monotone PR envelope)."""
    n_gt = sum(len(g) for g in gts.values())
    if n_gt == 0:
        return float("nan")
    preds = sorted(preds, key=lambda p: -p[1])           # global sort by score
    used = {k: np.zeros(len(v), bool) for k, v in gts.items()}
    tp = np.zeros(len(preds)); fp = np.zeros(len(preds))
    for i, (img, _, box) in enumerate(preds):
        g = gts.get(img, np.zeros((0, 4)))
        if len(g) == 0:
            fp[i] = 1; continue
        ious = iou_matrix(np.asarray(box, float)[None], g)[0]
        j = int(ious.argmax())
        if ious[j] >= iou_thr and not used[img][j]:
            tp[i] = 1; used[img][j] = True                 # first (highest-score) match wins
        else:
            fp[i] = 1                                      # duplicate or poor localisation
    tp, fp = np.cumsum(tp), np.cumsum(fp)
    recall = tp / n_gt
    precision = tp / np.maximum(tp + fp, 1e-9)
    # monotone envelope: precision at recall r = max precision at any recall >= r
    r = np.concatenate([[0.0], recall, [1.0]])
    p = np.concatenate([[1.0], precision, [0.0]])
    p = np.maximum.accumulate(p[::-1])[::-1]
    idx = np.where(r[1:] != r[:-1])[0]
    return float(np.sum((r[idx + 1] - r[idx]) * p[idx + 1]))

if __name__ == "__main__":
    gts = {0: np.array([[0, 0, 10, 10.]]), 1: np.array([[0, 0, 10, 10.], [20, 20, 30, 30.]])}
    preds = [(0, 0.9, [0, 0, 10, 10]), (1, 0.8, [0, 0, 10, 10]),
